/* main.c -- Inotia 4 (Inotia 4: Assassin of the Night) Switch loader
 *
 * The APK is a closed-source AArch64 build of Com2uS's Hercules engine with a
 * thin Java shell: the Java side owns the GL surface, the audio device and the
 * asset file descriptors, and forwards lifecycle calls into libgame.so.
 *
 * This file replaces that shell. It loads the original binary, answers its 231
 * imports (imports.c), stands in for the Java classes it calls (jni_fake.c),
 * brings up an ES 1.1 context itself (egl_helper.c) and then drives the same
 * three calls Android's GLSurfaceView made every frame:
 *
 *     nativeProcess  ->  the engine's update+draw  ->  eglSwapBuffers
 *
 * Ordering below mirrors MainActivity.onCreate / CRenderer.onSurfaceCreated;
 * getting it wrong is the most common cause of a black screen, so each step is
 * logged.
 */

